H=[['拉丁 damnum','损失、损害；罚金、处罚']]
D=H+[['古法语 damage / domage；动词 damagier','损害、损失；使受损'],['中古英语 → damage','损害；损坏；赔偿金用 damages']]
V=H+[['拉丁 damnāre → 古法语 damner → 中古英语 dampnen → damn','判定有罪、谴责 → 咒诅；咒骂词']]
C=H+[['拉丁 com- + damnāre → condemnāre','判罪、谴责'],['古法语 condamner → 中古英语 → condemn','谴责；判定、宣告某种不利结果']]
I=H+[['拉丁 in- 不 + damnum → indemnis','不受损害的']]
def A(h,a,b):return h+[[a,b]]
W=[
E('damage','/ˈdæmɪdʒ/','损害；损坏；使受损；赔偿金〔damages〕','东西原本完好，后来缺了一块、功能坏了或价值下降；不一定整个毁掉，只要受损就是 damage。','拉丁 damnum 经古法语 damage / domage；动词另接古法语 damagier。中间形式有不同词源分析，可靠共同来源是 damnum。',D,'名词表示损害通常不可数：some damage、damage to the roof。法律里的 damages 是赔偿金。动词可直接接宾语 damage the roof。','cause damage；damage to；damage a reputation；pay damages。','destroy 通常是摧毁；damage 是损害，程度可轻可重。普通“损坏”不能随意说 a damage。',('The storm caused serious damage to the roof.','暴风雨使屋顶严重受损。'),('False rumours can damage a person’s reputation.','不实传言会损害一个人的名誉。'),('The court awarded damages to the claimant.','法院判给了索赔方损害赔偿金。'),sources=['https://www.etymonline.com/word/damage','https://en.wiktionary.org/wiki/damage#English']),
E('damaging','/ˈdæmɪdʒɪŋ/','有害的；造成损害的','它关注的是谁在造成损害：一句话、一场风暴或一种做法会让别人受伤、受损。','damage + -ing；现在分词转作形容词。',A(D,'英语 damage + -ing → damaging','造成损害 → 有害的'),'damaging to 后接受损对象；damaging evidence 是对某方不利的证据，并不是证据本身破损了。','damaging to；damaging remarks；a damaging leak。','damaged 是已经受损；damaging 是会造成损害。a damaged phone 与 a damaging comment 方向不同。',('The allegation was damaging to the company’s reputation.','这项指控损害了公司的名誉。'),('They discussed the damaging effects of the delay.','他们讨论了延误造成的不良影响。')),
E('undamaged','/ʌnˈdæmɪdʒd/','未受损的；完好无损的','周围可能出了事故，但这件东西依然保持完整，没有受到所说的损害。','un- 不 + damaged；damaged 是 damage 的过去分词。',A(D,'damage → damaged；un- + damaged → undamaged','受损 → 未受损'),'常用来描述运输、风暴或事故后仍完好的东西。它只说没有损坏，不表示一定是全新、没有使用过。','remain undamaged；arrive undamaged；an undamaged copy。','new 是新的；undamaged 是未受损的。一件用了很久的物品也可以 undamaged。',('The glassware arrived undamaged.','玻璃器皿送到时完好无损。'),('Most of the books remained undamaged after the leak.','漏水后，大多数书仍未受损。')),
E('condemn','/kənˈdem/','谴责；判刑；宣告不适用；使陷于不幸','原本是作出不利判定：判某人有罪，判某个行为不可接受，或判一栋楼不再适合使用。','拉丁 com- 加强 + damnāre“判罪、谴责”，经古法语进入英语。',C,'condemn violence 是强烈谴责；condemn a building 是宣告建筑不适合使用；condemn someone to 是判处或使其注定承受某种境况。词末 n 通常不发音。','condemn an action；condemn someone to；a condemned building。','criticise 可轻可重；condemn 通常是明确而强烈的否定。condemn 与 condone“宽恕、容忍”意思差别很大。',('The organisation condemned the attack.','该组织谴责了这次袭击。'),('The building was condemned as unsafe.','这栋楼被判定不安全，不适合继续使用。'),('The decision condemned the project to years of delay.','这个决定让项目陷入了多年的拖延。')),
E('condemnation','英 /ˌkɒndəmˈneɪʃən/；美 /ˌkɑːndəmˈneɪʃən/','谴责；判罪；宣告不适用；征收〔美国财产法语境〕','把 condemn 的不利判断变成一项行为或结果：公开强烈反对，或作出正式处置。','拉丁 condemnātiō 进入中古英语；与 condemn 是相关的不同借入形式。',[H[0],['拉丁 condemnāre → condemnātiō → 中古英语 condempnacioun','谴责、判罪 → 谴责或判定行为'],['现代英语 condemnation','谴责；特定法律处置']],'日常新闻最常见 widespread condemnation。美国财产法中还可指通过征收权取得私人财产的程序，不能在这个语境机械译成“责骂土地”。','widespread condemnation；a statement of condemnation；condemnation proceedings。','condemn 末尾 n 不读，但 condemnation 的 /neɪ/ 中 n 要读出来；这是词族内的发音变化。',('The proposal drew widespread condemnation.','这项提议招致了广泛谴责。'),('The lawyer explained the term condemnation in a property dispute.','律师解释了财产争议中 condemnation 一词的法律含义。'),sources=['https://en.wiktionary.org/wiki/condemnation#English','https://www.law.cornell.edu/wex/condemnation']),
E('damn','/dæm/','咒诅；严厉批评；该死〔咒骂词〕；一点在乎〔固定表达〕','从“判有罪、判受罚”走到宗教中的咒诅，再弱化成日常表达恼怒或加强语气的词。','拉丁 damnāre 经古法语 damner、中古英语 dampnen 等形式进入；不是 dam“水坝”的派生词。',V,'Damn! 可表示懊恼；not give a damn 表示一点也不在乎。动词也可说评论把作品批得很坏。日常咒骂用法带粗俗、冒犯色彩，正式场合一般换更中性的说法。','damn with faint praise；not give a damn；Damn!。','dam 是水坝，与 damn 常同音但另源。damn 中 n 不发音，damnation 中则出现 /n/。',('“Damn, I forgot my keys,” he muttered.','“该死，我忘带钥匙了，”他嘟囔道。'),('The reviewer damned the film with faint praise.','评论者用不痛不痒的夸奖，实际贬低了这部电影。'),('She did not give a damn about the gossip.','她一点也不在乎那些闲话。'),sources=['https://www.etymonline.com/word/damn']),
E('damned','/dæmd/','该死的；非常〔粗俗强调〕；被诅咒的〔宗教、文学〕','damn 的受事状态原本是遭到判罚或诅咒；日常后来常变成带火气的强调词。','damn 的过去分词、形容词用法；中古英语已有 dampned。',A(V,'英语 damn → damned','受谴责、受诅咒 → 表恼怒或强烈程度'),'a damned nuisance 是很讨厌的麻烦；damned good 可以加强称赞，未必真在诅咒。the damned 在宗教语境指被判受永罚者。','a damned nuisance；damned good；the damned。','damned 的语气通常比 very 粗，带情绪。它不等于 damaged“损坏的”，虽有共同远源，现代词义不同。',('This lock is a damned nuisance.','这把锁真是个讨厌的麻烦。'),('That was a damned good performance.','那场表演真够精彩的。'),('The painting depicts the damned in a religious vision.','画作描绘了宗教幻象中受永罚的人。')),
E('damning','/ˈdæmɪŋ/','极为不利的；有力揭露问题的；严厉谴责的','一份材料让人很难再为某种行为开脱，仿佛把“有问题”这个判断钉得很牢。','damn + -ing；分词转作形容词。',A(V,'英语 damn + -ing → damning','使受谴责 → 对某方极不利、揭露问题的'),'a damning report 是揭露严重问题的报告；damning evidence 通常说证据非常不利。它表达评价力度，并不自动替代正式法律裁决。','damning evidence；a damning report；a damning indictment。','damaging 可以泛指造成损害；damning 常突出材料强烈指向错误、失败或责任。',('The audit produced a damning report on the project’s management.','审计报告严厉揭露了项目管理中的问题。'),('The emails contained damning evidence of the deception.','邮件中包含了对这场欺骗极为不利的证据。')),
E('damnation','/dæmˈneɪʃən/','永罚；被判堕入地狱；诅咒〔宗教、文学〕','在宗教叙述里，审判把人判向来世的惩罚；这个词把那种被判罚的状态或结果拿出来说。','拉丁 damnātiō，经古法语 dampnacion 进入中古英语；并不是现代英语在 damn 后才临时加 -ation。',[H[0],['拉丁 damnāre → damnātiō → 古法语 dampnacion','判罚 → 受判罚的状态、结果'],['英语 damnation','尤其指宗教中的永罚']],'常与 salvation“救赎”相对。也能作为较旧的感叹词，但阅读神学、古典文学时先认出永罚这一核心语境。','eternal damnation；fear of damnation；salvation and damnation。','condemnation 通常是谴责或正式判定；damnation 更强烈地带来世惩罚的宗教背景。',('The poem explores the contrast between salvation and damnation.','诗歌探讨了救赎与永罚的对照。'),('The character is haunted by the fear of damnation.','这个人物一直被遭受永罚的恐惧困扰。')),
E('indemnity','/ɪnˈdemnəti/','损失补偿；赔偿保障；赔偿责任安排','in- 是否定，damnum 是损失：承诺让另一方不必独自吞下某些损失，或在损失发生后给予补偿。','拉丁 indemnis“不受损”→ 后期拉丁 indemnitās → 法语 indemnité → 英语。',[I[0],I[1],['后期拉丁 indemnitās → 法语 indemnité → 英语 indemnity','免于损失的保障；补偿']],'常见于保险和合同，涉及对特定损失的补偿或责任承担。所覆盖的损失要看具体约定，词本身不表示任何损失都无限赔。','professional indemnity insurance；an indemnity clause；an indemnity against loss。','compensation 是更宽泛的补偿；indemnity 更常用于特定损失与法律责任的保障安排。',('The contract includes an indemnity clause.','合同包含一项赔偿保障条款。'),('The firm carries professional indemnity insurance.','这家公司投保了专业责任保险。'),sources=['https://en.wiktionary.org/wiki/indemnity#English','https://www.law.cornell.edu/wex/indemnify']),
E('indemnify','/ɪnˈdemnɪfaɪ/','赔偿；补偿损失；保障免受某项损失','某项损失落到了你身上，另一方承诺承担或补回来，让你不必独自承受。','indemn“不受损的”，接拉丁 indemnis + -ify“使成为”；英语构词。',A(I,'英语 indemn + -ify → indemnify','使不受损 → 补偿、承担特定损失'),'常说 indemnify someone against loss 或 for specified costs。它是赔偿安排的动词，不能理解为事情从此绝不会发生。旧文献另有极罕见的伤害义，来源分析不同，现代先掌握补偿义。','indemnify someone against；indemnify someone for。','insure 是投保或承保；indemnify 是补偿、承担损失，保险合同可包含这种义务，但两词不总互换。',('The agreement requires one party to indemnify the other for specified losses.','协议要求一方赔偿另一方的特定损失。'),('The policy may indemnify the insured against certain costs.','该保单可能对被保险人的某些费用提供赔偿。'),sources=['https://www.law.cornell.edu/wex/indemnify','https://en.wiktionary.org/wiki/indemnify#English']),
E('indemnification','/ɪnˌdemnɪfɪˈkeɪʃən/','赔偿；损失补偿安排','把 indemnify 的补偿动作或义务变成名词，用来讨论是否赔、赔哪些损失以及谁承担。','indemnify 对应 -ification；构词时 -ify 变为 -ification。',A(I,'英语 indemnify → indemnification','补偿、保障 → 补偿行为或安排'),'常作合同标题的一部分，如 indemnification provisions。它与 indemnity 有重叠，前者常突出行为、过程或条款安排，不能硬造处处适用的区别。','an indemnification agreement；seek indemnification；indemnification provisions。','indemnification 不是 identification“识别、身份证明”；中间的 -demn- 仍关联损失。',('The parties negotiated the indemnification provisions.','双方协商了损失补偿条款。'),('The company sought indemnification for the expenses covered by the agreement.','公司要求赔偿协议所涵盖的费用。'),sources=['https://www.law.cornell.edu/wex/indemnify','https://en.wiktionary.org/wiki/indemnification#English']),
]
ROOT=dict(id='C0303',meaning='损失、损害；判罚与谴责',core='DAMN / DEMN = LOSS; CONDEMN',image='先看账本上出现一笔损失，再看谁要为这笔损失承担不利后果。damnum 的损失与 damnare 的判罚连在一起；否定它的 indemnis 则是“不让损失落在身上”。',intro='拉丁 damnum 表示损失、损害，也可涉及罚金；damnāre 发展出判罪、谴责。英语 damage 保留实际受损的方向，condemn 保留不利判断，damn 进一步用于宗教咒诅与日常咒骂；indemnity 从“不受损”走向赔偿保障。',forms='damn- 可在相关复合词中呈现 -demn-。damn /dæm/、condemn /kənˈdem/ 中 n 不读；damnation、condemnation、indemnity 中 n 出现。不要把这些字母变化当成可以随意套用到任何单词的拼写规则。',branches=[['实际受损','damage, damaging, undamaged'],['判定与谴责','condemn, condemnation, damning'],['诅咒与强调','damn, damned, damnation'],['补偿与承担损失','indemnity, indemnify, indemnification']],contrasts='damaged 是受损，damaging 是造成损害，damning 是强烈揭露问题。dam“水坝”与 damn 同音却另源。indemnity 的 in- 是否定，方向是保障或补偿，而不是加重损失。',practice='The report was damning, but the real damage had already been done. The parties then discussed whether the agreement required indemnification.\n\n报告揭露的问题十分严重，但实际损害已经造成。随后，双方讨论协议是否要求作出赔偿。',words=[w['word'] for w in W])
